import { Controller, Get, Post, Patch, Delete, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
// 가정: 같은 기간(시작일·종료일)과 자금과목이면 중복 계획으로 본다.

type Db = Parameters<Parameters<typeof transaction>[0]>[0];

const PLAN_COLS = `
  fund_plan_id AS "fundPlanId",
  to_char(plan_start_date, 'YYYY-MM-DD') AS "planStartDate",
  to_char(plan_end_date, 'YYYY-MM-DD') AS "planEndDate",
  fund_subject_id AS "fundSubjectId",
  cash_direction AS "cashDirection",
  plan_amount AS "planAmount",
  fixed_fund_id AS "fixedFundId"`;

function fail(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function isDate(v: unknown): v is string {
  return typeof v === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(v);
}

function toAmount(v: unknown): string | null {
  if (typeof v === 'number' && Number.isFinite(v) && v >= 0) {
    return String(v);
  }
  if (typeof v === 'string' && /^\d+(\.\d{1,2})?$/.test(v.trim())) {
    return v.trim();
  }
  return null;
}

function toId(v: unknown): string | null {
  if (typeof v === 'number' && Number.isInteger(v) && v > 0) {
    return String(v);
  }
  if (typeof v === 'string' && /^\d+$/.test(v.trim())) {
    return v.trim();
  }
  return null;
}

function opt(v: unknown): string | null {
  if (v === undefined || v === null || v === '') {
    return null;
  }
  return String(v);
}

interface Plan {
  start: string;
  end: string;
  subjectId: string;
  direction: string;
  amount: string;
  fixedId: string | null;
}

function resolvePlan(data: Record<string, unknown>, base: Record<string, unknown>): Plan {
  const pick = (k: string): unknown => (data[k] !== undefined ? data[k] : base[k]);
  const start = pick('planStartDate');
  if (!isDate(start)) {
    throw fail('계획 시작일을 YYYY-MM-DD 형식으로 입력해 주세요.');
  }
  const end = pick('planEndDate');
  if (!isDate(end)) {
    throw fail('계획 종료일을 YYYY-MM-DD 형식으로 입력해 주세요.');
  }
  if (end < start) {
    throw fail('계획 종료일은 시작일보다 빠를 수 없습니다.');
  }
  const subjectId = toId(pick('fundSubjectId'));
  if (subjectId === null) {
    throw fail('자금과목을 선택해 주세요.');
  }
  const direction = pick('cashDirection');
  if (direction !== '입금' && direction !== '출금') {
    throw fail('입출금 구분은 입금 또는 출금이어야 합니다.');
  }
  const amount = toAmount(pick('planAmount'));
  if (amount === null) {
    throw fail('계획 금액은 0 이상의 숫자여야 합니다.');
  }
  const rawFixed = data.fixedFundId !== undefined ? data.fixedFundId : base.fixedFundId;
  let fixedId: string | null = null;
  if (rawFixed !== undefined && rawFixed !== null && rawFixed !== '') {
    fixedId = toId(rawFixed);
    if (fixedId === null) {
      throw fail('고정자금 값이 올바르지 않습니다.');
    }
  }
  return { start, end, subjectId, direction, amount, fixedId };
}

async function verifyPlan(db: Db, p: Plan, selfId: string | null, checkSubject: boolean): Promise<void> {
  if (checkSubject) {
    const subjects = await db.query(
      'SELECT use_yn AS "useYn" FROM fund_subject WHERE fund_subject_id = CAST(:id AS bigint)',
      { id: p.subjectId },
    );
    if (subjects.length === 0) {
      throw fail('존재하지 않는 자금과목입니다.');
    }
    if (subjects[0].useYn !== '사용') {
      throw new ApiError(422, 'FUND_SUBJECT_NOT_IN_USE', '미사용 자금과목은 지정할 수 없습니다.');
    }
  }
  if (p.fixedId !== null) {
    const fixed = await db.query(
      'SELECT fixed_fund_id FROM fixed_fund WHERE fixed_fund_id = CAST(:id AS bigint)',
      { id: p.fixedId },
    );
    if (fixed.length === 0) {
      throw fail('존재하지 않는 고정자금입니다.');
    }
  }
  const dup = await db.query(
    `SELECT fund_plan_id FROM fund_plan
     WHERE plan_start_date = CAST(:start AS date)
       AND plan_end_date = CAST(:end AS date)
       AND fund_subject_id = CAST(:subjectId AS bigint)
       AND (CAST(:selfId AS bigint) IS NULL OR fund_plan_id <> CAST(:selfId AS bigint))`,
    { start: p.start, end: p.end, subjectId: p.subjectId, selfId },
  );
  if (dup.length > 0) {
    throw new ApiError(409, 'FUND_PLAN_DUPLICATED', '동일 기간·자금과목의 계획이 이미 있습니다. 기존 계획을 수정해 주세요.');
  }
}

@Controller('api/v1')
export class FnSfr00902Controller {
  @Get('/fund-plans')
  async listFundPlans(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query) as Record<string, unknown>;
    const pageRaw = opt(q.page);
    const sizeRaw = opt(q.size);
    const page = pageRaw === null ? 0 : Number(pageRaw);
    let size = sizeRaw === null ? DEFAULT_SIZE : Number(sizeRaw);
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
      throw fail('page·size 값이 올바르지 않습니다.');
    }
    if (size > MAX_SIZE) {
      size = MAX_SIZE;
    }
    const fromDate = opt(q.fromDate);
    const toDate = opt(q.toDate);
    if ((fromDate !== null && !isDate(fromDate)) || (toDate !== null && !isDate(toDate))) {
      throw fail('조회 기간을 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    const subjectRaw = opt(q.fundSubjectId);
    const fundSubjectId = subjectRaw === null ? null : toId(subjectRaw);
    if (subjectRaw !== null && fundSubjectId === null) {
      throw fail('자금과목 값이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const where = `WHERE (CAST(:fromDate AS date) IS NULL OR plan_end_date >= CAST(:fromDate AS date))
        AND (CAST(:toDate AS date) IS NULL OR plan_start_date <= CAST(:toDate AS date))
        AND (CAST(:fundSubjectId AS bigint) IS NULL OR fund_subject_id = CAST(:fundSubjectId AS bigint))`;
      const filter = { fromDate, toDate, fundSubjectId };
      const counts = await db.query(`SELECT COUNT(*) AS "total" FROM fund_plan ${where}`, filter);
      const items = await db.query(
        `SELECT ${PLAN_COLS} FROM fund_plan ${where}
         ORDER BY plan_start_date DESC, fund_plan_id DESC
         LIMIT CAST(:size AS int) OFFSET CAST(:offset AS int)`,
        { ...filter, size, offset: page * size },
      );
      return { items, page, size, total: Number(counts[0].total) };
    });
  }

  @Post('/fund-plans')
  @HttpCode(200)
  async createFundPlan(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body) as Record<string, unknown>;
    const plan = resolvePlan(data, {});
    return transaction(async (db) => {
      await verifyPlan(db, plan, null, true);
      const rows = await db.query(
        `INSERT INTO fund_plan (plan_start_date, plan_end_date, fund_subject_id, cash_direction, plan_amount, fixed_fund_id, created_at, updated_at)
         VALUES (CAST(:start AS date), CAST(:end AS date), CAST(:subjectId AS bigint), :direction, CAST(:amount AS numeric), CAST(:fixedId AS bigint), now(), now())
         RETURNING fund_plan_id AS "fundPlanId"`,
        plan as unknown as Record<string, unknown>,
      );
      return { fundPlanId: rows[0].fundPlanId };
    });
  }

  @Patch('/fund-plans/:fundPlanId')
  @HttpCode(200)
  async updateFundPlan(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = toId(req.params['fundPlanId']);
    if (id === null) {
      throw fail('자금수지계획 ID가 올바르지 않습니다.');
    }
    const data = checks.inputOf(req.body) as Record<string, unknown>;
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT ${PLAN_COLS} FROM fund_plan WHERE fund_plan_id = CAST(:id AS bigint)`,
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'FUND_PLAN_NOT_FOUND', '자금수지계획을 찾을 수 없습니다.');
      }
      const plan = resolvePlan(data, rows[0] as Record<string, unknown>);
      await verifyPlan(db, plan, id, data.fundSubjectId !== undefined);
      await db.execute(
        `UPDATE fund_plan SET
           plan_start_date = CAST(:start AS date),
           plan_end_date = CAST(:end AS date),
           fund_subject_id = CAST(:subjectId AS bigint),
           cash_direction = :direction,
           plan_amount = CAST(:amount AS numeric),
           fixed_fund_id = CAST(:fixedId AS bigint),
           updated_at = now()
         WHERE fund_plan_id = CAST(:id AS bigint)`,
        { ...plan, id },
      );
      return { fundPlanId: rows[0].fundPlanId };
    });
  }

  @Delete('/fund-plans/:fundPlanId')
  @HttpCode(200)
  async deleteFundPlan(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = toId(req.params['fundPlanId']);
    if (id === null) {
      throw fail('자금수지계획 ID가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const count = await db.execute(
        'DELETE FROM fund_plan WHERE fund_plan_id = CAST(:id AS bigint)',
        { id },
      );
      if (count === 0) {
        throw new ApiError(404, 'FUND_PLAN_NOT_FOUND', '자금수지계획을 찾을 수 없습니다.');
      }
      return {};
    });
  }
}

