import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  Field,
  Filters,
  Form,
  LookupSelect,
  Num,
  NumberInput,
  Pager,
  Pairs,
  RefName,
  Select,
  Tiles,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const SIZE = 20;

type Mode =
  | { kind: 'create' }
  | { kind: 'view'; row: Row }
  | { kind: 'edit'; row: Row }
  | { kind: 'delete'; row: Row }
  | null;

function PlanForm({ role, row, onDone }: { role: string; row?: Row; onDone: (text: string) => void }) {
  const [start, setStart] = useState<unknown>(row?.planStartDate ?? '');
  const [end, setEnd] = useState<unknown>(row?.planEndDate ?? '');
  const [subject, setSubject] = useState<unknown>(row?.fundSubjectId ?? '');
  const [direction, setDirection] = useState<unknown>(row?.cashDirection ?? '');
  const [amount, setAmount] = useState<unknown>(row?.planAmount ?? '');
  const [fixed, setFixed] = useState<unknown>(row?.fixedFundId ?? '');

  const submit = async () => {
    if (!start || !end || !subject || !direction || amount === '' || amount === null || amount === undefined) {
      throw new Error('계획 시작일, 계획 종료일, 자금과목, 입출금 구분, 계획 금액은 필수입니다.');
    }
    const body: Row = {
      planStartDate: start,
      planEndDate: end,
      fundSubjectId: subject,
      cashDirection: direction,
      planAmount: amount,
      fixedFundId: fixed === '' ? null : fixed,
    };
    if (row) {
      await call('PATCH', '/fund-plans/' + String(row.fundPlanId), role, body);
      onDone('자금수지계획을 수정했습니다.');
    } else {
      if (fixed === '') {
        delete body.fixedFundId;
      }
      await call('POST', '/fund-plans', role, body);
      onDone('자금수지계획을 등록했습니다.');
    }
  };

  return (
    <Form onSubmit={submit} submit={row ? '수정' : '등록'}>
      <Field label='계획 시작일' required>
        <DateInput value={start} onChange={setStart} />
      </Field>
      <Field label='계획 종료일' required>
        <DateInput value={end} onChange={setEnd} />
      </Field>
      <Field label='자금과목' required>
        <LookupSelect table='fund_subject' role={role} value={subject} onChange={setSubject} />
      </Field>
      <Field label='입출금 구분' required>
        <Select
          value={direction}
          onChange={setDirection}
          options={[['입금', '입금'], ['출금', '출금']]}
        />
      </Field>
      <Field label='계획 금액' required>
        <NumberInput value={amount} onChange={setAmount} />
      </Field>
      <Field label='반영할 고정자금' hint='고정자금을 반영할 때만 고릅니다.'>
        <LookupSelect table='fixed_fund' role={role} value={fixed} onChange={setFixed} />
      </Field>
    </Form>
  );
}

export default function FnSfr00902Page({ role, notify }: PageProps) {
  const [fromDate, setFromDate] = useState('');
  const [toDate, setToDate] = useState('');
  const [subject, setSubject] = useState<unknown>('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [mode, setMode] = useState<Mode>(null);

  const { data, error, loading, reload } = useData<Page>(
    () => call<Page>('GET', '/fund-plans', role, undefined, { ...applied, page, size: SIZE }),
    [applied, page, role],
  );

  const rows = data?.items ?? [];
  const sum = (direction: string) =>
    rows
      .filter((r) => r.cashDirection === direction)
      .reduce((acc, r) => acc + Number(r.planAmount ?? 0), 0);

  const search = () => {
    setPage(0);
    setApplied({ fromDate, toDate, fundSubjectId: subject });
  };
  const reset = () => {
    setFromDate('');
    setToDate('');
    setSubject('');
    setPage(0);
    setApplied({});
  };
  const done = (text: string) => {
    setMode(null);
    notify(text);
    reload();
  };
  const remove = async (row: Row) => {
    await call('DELETE', '/fund-plans/' + String(row.fundPlanId), role);
    done('자금수지계획을 삭제했습니다.');
  };

  return (
    <div className='bento'>
      <section className='box span-12'>
        <h2>계획 현황</h2>
        <Tiles
          items={[
            ['전체 계획', <Num value={data?.total ?? 0} />],
            ['입금 계획 (현재 쪽)', <Num value={sum('입금')} />],
            ['출금 계획 (현재 쪽)', <Num value={sum('출금')} />],
          ]}
        />
      </section>

      <section className='box span-12'>
        <h2>자금수지계획</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label='조회 시작일'>
            <DateInput value={fromDate} onChange={setFromDate} />
          </Field>
          <Field label='조회 종료일'>
            <DateInput value={toDate} onChange={setToDate} />
          </Field>
          <Field label='자금과목'>
            <LookupSelect table='fund_subject' role={role} value={subject} onChange={setSubject} />
          </Field>
        </Filters>
        <Band total={data?.total}>
          <button type='button' onClick={() => setMode({ kind: 'create' })}>
            계획 등록
          </button>
        </Band>
        {error ? <p>{error}</p> : null}
        <DataTable
          columns={[
            { key: 'planStartDate', label: '계획 시작일', render: (r) => <DateText value={r.planStartDate} /> },
            { key: 'planEndDate', label: '계획 종료일', render: (r) => <DateText value={r.planEndDate} /> },
            {
              key: 'fundSubjectId',
              label: '자금과목',
              render: (r) => <RefName table='fund_subject' role={role} value={r.fundSubjectId} />,
            },
            { key: 'cashDirection', label: '입출금 구분', render: (r) => <Badge value={r.cashDirection} /> },
            { key: 'planAmount', label: '계획 금액', render: (r) => <Num value={r.planAmount} /> },
            {
              key: 'fixedFundId',
              label: '참조 고정자금',
              render: (r) =>
                r.fixedFundId ? <RefName table='fixed_fund' role={role} value={r.fixedFundId} /> : <span>-</span>,
            },
          ]}
          rows={rows}
          onRowClick={(r) => setMode({ kind: 'view', row: r })}
          empty={loading ? '불러오는 중입니다.' : '등록된 자금수지계획이 없습니다.'}
        />
        <Pager page={data?.page ?? page} size={data?.size ?? SIZE} total={data?.total ?? 0} onPage={setPage} />
      </section>

      {mode?.kind === 'create' ? (
        <Drawer title='자금수지계획 등록' onClose={() => setMode(null)}>
          <PlanForm role={role} onDone={done} />
        </Drawer>
      ) : null}

      {mode?.kind === 'edit' ? (
        <Drawer title='자금수지계획 수정' onClose={() => setMode(null)}>
          <PlanForm role={role} row={mode.row} onDone={done} />
        </Drawer>
      ) : null}

      {mode?.kind === 'view' ? (
        <Drawer title='자금수지계획 상세' onClose={() => setMode(null)}>
          <Pairs
            items={[
              ['계획 시작일', <DateText value={mode.row.planStartDate} />],
              ['계획 종료일', <DateText value={mode.row.planEndDate} />],
              ['자금과목', <RefName table='fund_subject' role={role} value={mode.row.fundSubjectId} />],
              ['입출금 구분', <Badge value={mode.row.cashDirection} />],
              ['계획 금액', <Num value={mode.row.planAmount} />],
              [
                '참조 고정자금',
                mode.row.fixedFundId ? (
                  <RefName table='fixed_fund' role={role} value={mode.row.fixedFundId} />
                ) : (
                  <span>-</span>
                ),
              ],
            ]}
          />
          <Band>
            <button type='button' onClick={() => setMode({ kind: 'edit', row: mode.row })}>
              수정
            </button>
            <button type='button' onClick={() => setMode({ kind: 'delete', row: mode.row })}>
              삭제
            </button>
          </Band>
        </Drawer>
      ) : null}

      {mode?.kind === 'delete' ? (
        <Drawer title='자금수지계획 삭제' onClose={() => setMode(null)}>
          <Form
            danger
            submit='삭제'
            note='이 자금수지계획을 삭제합니다. 삭제한 계획은 되돌릴 수 없습니다.'
            onSubmit={() => remove(mode.row)}
          />
        </Drawer>
      ) : null}
    </div>
  );
}
